# ============================================================
# 一键安装 WSL 里的嵌套 GNOME 桌面（自包含：脚本内含安装包，复制给别人也能用）
#
# 支持的发行版（自动识别 apt/dnf）：
#   Ubuntu / Kali / Debian          → apt（装 kali-desktop-gnome / ubuntu-desktop / gnome）
#   Fedora / Oracle Linux / RHEL    → dnf（有 mutter-devkit 用 devkit，否则装 GNOME 47 用 nested）
#
# 用法（Windows PowerShell）：
#   powershell -ExecutionPolicy Bypass -File .\install.ps1
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -Distro FedoraLinux-45
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -Distro oracle-linux-10
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -All            # 所有已装发行版都装
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -DryRun         # 只检查，不改动
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -SkipPackages   # 已装好组件，只配置
#   powershell -ExecutionPolicy Bypass -File .\install.ps1 -NoStart        # 装完不启动桌面
#
# 参数：
#   -Distro <名字>   发行版名（wsl -l -v 查看；默认自动：有 Ubuntu 用 Ubuntu，否则用第一个）
#   -User <名字>     指定用户（默认用发行版里的普通用户；没有会自动创建 u）
#   -All             对所有已安装发行版逐个安装
#   -DryRun          只检查，不做改动
#   -SkipPackages    跳过 apt/dnf 安装（别名 -SkipApt）
#   -NoStart         安装完不自动启动桌面
# ============================================================
param(
    [string]$Distro = '',
    [string]$User = '',
    [switch]$DryRun,
    [Alias('SkipApt')][switch]$SkipPackages,
    [switch]$NoStart,
    [switch]$All
)
$ErrorActionPreference = 'Stop'
$env:WSL_UTF8 = '1'

function Info([string]$m) { Write-Host "  $m" }
function Step([string]$m) { Write-Host "`n===== $m =====" -ForegroundColor Cyan }
function Warn([string]$m) { Write-Host "  [!] $m" -ForegroundColor Yellow }
function Fail([string]$m) { Write-Host "`n[失败] $m" -ForegroundColor Red; exit 1 }

# 安装包（base64 tar.gz，由仓库脚本生成，内含 wsl-desktop/ 全部文件）
$PayloadBase64 = @'

'@

function Get-Distros {
    $raw = & wsl.exe -l -q 2>$null
    if (-not $raw) { return @() }
    $list = @()
    foreach ($line in $raw) {
        $name = (($line -replace "`0", '')).Trim()
        if ($name -and $name -notmatch '^docker-desktop') { $list += $name }
    }
    return $list
}

function Test-Distro([string]$d) {
    & wsl.exe -d $d -u root -- true 2>$null | Out-Null
    return ($LASTEXITCODE -eq 0)
}

function Get-DefaultUser([string]$d) {
    $u = ((& wsl.exe -d $d -- id -un 2>$null) -join '').Trim()
    if ($u -and $u -ne 'root') { return $u }
    # 默认用户是 root：如果安装器已经建好 u，就用 u
    $hasU = ((& wsl.exe -d $d -u root -- getent passwd u 2>$null) -join '').Trim()
    if ($hasU) { return 'u' }
    return $u
}

function Extract-Payload([string]$d) {
    $b64Path = Join-Path $env:TEMP 'wsl-desktop-payload.b64'
    Set-Content -Path $b64Path -Value ($PayloadBase64 -replace '\s', '') -NoNewline -Encoding Ascii
    $extract = "(command -v tar >/dev/null 2>&1 || dnf install -y tar >/dev/null 2>&1 || apt-get install -y tar >/dev/null 2>&1 || true) && tr -d '\r' | base64 -d > /tmp/wsl-desktop.tar.gz && rm -rf /opt/wsl-desktop && mkdir -p /opt && tar -xzf /tmp/wsl-desktop.tar.gz -C /opt && find /opt/wsl-desktop -type f \( -name '*.sh' -o -name '*.js' -o -name '*.json' -o -name '*.service' \) -exec sed -i 's/\r`$//' {} + && chmod 0755 /opt/wsl-desktop/install.sh && echo EXTRACTED"
    $out = ((Get-Content $b64Path -Raw) | & wsl.exe -d $d -u root -- bash -lc $extract 2>&1) -join "`n"
    if ($out -notmatch 'EXTRACTED') { throw "解包安装包失败：$out" }
}

function Install-One([string]$d) {
    Step "安装到 $d"
    if (-not (Test-Distro $d)) { throw "无法进入发行版 '$d'（用 wsl -l -v 查看正确名字）" }

    $wslgExit = 1
    & wsl.exe -d $d -u root -- test -S /mnt/wslg/PulseServer 2>$null | Out-Null
    $wslgExit = $LASTEXITCODE
    if ($wslgExit -ne 0) { Warn '没检测到 /mnt/wslg/PulseServer（WSLg 可能没启用，桌面窗口会显示不出来）' }

    if ($DryRun) {
        Info "将：解包到 /opt/wsl-desktop → 安装桌面组件 → 配置音频/剪贴板 → 启动桌面"
        return [pscustomobject]@{ Distro = $d; User = ''; Ok = $true; Message = 'DryRun' }
    }

    Info '解包安装包…'
    Extract-Payload $d

    $flags = @()
    if ($SkipPackages) { $flags += '--skip-packages' }
    if ($User) { $flags += "--user=$User" }
    $cmd = "bash /opt/wsl-desktop/install.sh " + ($flags -join ' ')

    Info '运行安装器（首次会下载 1~3 GB，请耐心等待）…'
    $out = @(& wsl.exe -d $d -u root -- bash -lc $cmd 2>&1)
    $code = $LASTEXITCODE
    $text = $out -join "`n"

    if ($code -eq 3) {
        Warn '这个发行版还没启用 systemd，正在重启发行版后重试…'
        & wsl.exe --terminate $d 2>$null | Out-Null
        Start-Sleep -Seconds 3
        for ($i = 0; $i -lt 10; $i++) {
            $out = @(& wsl.exe -d $d -u root -- bash -lc $cmd 2>&1)
            $code = $LASTEXITCODE
            $text = $out -join "`n"
            if ($code -ne 3) { break }
            Start-Sleep -Seconds 2
        }
    }
    if ($code -ne 0) { throw "install.sh 失败（退出码 $code）：`n$text" }

    $u = $User
    if (-not $u) {
        foreach ($line in $out) {
            if ("$line" -match '^WSL_DESKTOP_USER=(.+)$') { $u = $Matches[1].Trim(); break }
        }
    }
    if (-not $u) { $u = Get-DefaultUser $d }
    if (-not $u -or $u -eq 'root') { throw "找不到可用的普通用户（GNOME 不能以 root 运行）：$text" }

    $mode = ''
    foreach ($line in $out) {
        if ("$line" -match '^WSL_DESKTOP_MODE=(.+)$') { $mode = $Matches[1].Trim() }
    }

    $started = $false
    if (-not $NoStart) {
        Info "启动桌面（用户 $u）…"
        $startOut = @(& wsl.exe -d $d -u $u -- bash -lc '~/start-desktop.sh' 2>&1)
        foreach ($line in $startOut) { Info $line }
        $started = $true
    }

    return [pscustomobject]@{ Distro = $d; User = $u; Mode = $mode; Started = $started; Ok = $true; Message = '' }
}

# ---------- 选发行版 ----------
if ($All) {
    $distros = Get-Distros
    if ($distros.Count -eq 0) { Fail '一个 WSL 发行版都没找到。' }
} elseif ($Distro) {
    $distros = @($Distro)
} else {
    $all = Get-Distros
    if ($all.Count -eq 0) { Fail '一个 WSL 发行版都没找到。请先 wsl --install -d Ubuntu。' }
    if ($all -contains 'Ubuntu') { $distros = @('Ubuntu') }
    else { $distros = @($all[0]) }
}

Write-Host 'WSL 嵌套 GNOME 桌面 —— 一键安装' -ForegroundColor Green
Info ("目标发行版：" + ($distros -join ', '))
Info ("选项：" + ((@(
    $(if ($DryRun) { 'DryRun' }),
    $(if ($SkipPackages) { 'SkipPackages' }),
    $(if ($NoStart) { 'NoStart' }),
    $(if ($User) { "User=$User" })
) | Where-Object { $_ }) -join ' '))

$results = @()
foreach ($d in $distros) {
    try {
        $results += (Install-One $d)
    } catch {
        Warn "安装 $d 失败：$($_.Exception.Message)"
        $results += [pscustomobject]@{ Distro = $d; User = ''; Ok = $false; Message = $_.Exception.Message }
    }
}

# ---------- 汇总 ----------
Write-Host "`n===== 结果 =====" -ForegroundColor Cyan
foreach ($r in $results) {
    if ($r.Ok) {
        Write-Host ("  [OK]   {0,-22} 用户：{1,-8} {2}" -f $r.Distro, $r.User, $r.Message) -ForegroundColor Green
    } else {
        Write-Host ("  [FAIL] {0,-22} {1}" -f $r.Distro, $r.Message) -ForegroundColor Red
    }
}

if ($results | Where-Object { -not $_.Ok }) { exit 1 }

if (-not $DryRun) {
    Write-Host ''
    Info '以后启动桌面：'
    foreach ($r in $results) {
        Info ("  powershell -ExecutionPolicy Bypass -File .\start-desktop.ps1 -Distro " + $r.Distro)
        Info ("  （或 WSL 里：wsl -d " + $r.Distro + " -u " + $r.User + " -- bash -lc '~/start-desktop.sh'）")
    }
    Info ''
    Info '窗口标题：devkit 模式是「Mutter Development Kit (发行版)」，nested 模式是「gnome-shell (发行版)」。'
    Info '关闭窗口 = 关闭桌面；重新运行 start-desktop.ps1 即可。'
}
exit 0
